commit ea98ef6eb3061b2d4a15ef9a46255b02619fe974
Author: Vineet Deo <vineet@thunderbird.net>
Date:   Fri Jun 7 06:23:22 2024 +0000

    Bug 1675212 - Prevent deleting multiple messages when holding delete. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D212650

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index 41dfc0b2c92..feb02032680 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -4106,6 +4106,13 @@ var threadPane = {
       return;
     }

+    if ((event.key == "Backspace" || event.key == "Delete") && event.repeat) {
+      // Bail on delete event if there is a repeat event to prevent deleteing
+      // multiple messages by mistake from a longer key press.
+      event.preventDefault();
+      return;
+    }
+
     if (event.key == "Enter") {
       this._onItemActivate(event);
     }
diff --git a/mail/base/content/mailWindow.js b/mail/base/content/mailWindow.js
index 2679a9c3f66..f80a437cea9 100644
--- a/mail/base/content/mailWindow.js
+++ b/mail/base/content/mailWindow.js
@@ -1108,6 +1108,15 @@ window.addEventListener("aboutMessageLoaded", event => {
   );
   // Also add a copy listener so we can process images.
   event.target.document.addEventListener("copy", onCopyOrDragStart, true);
+
+  event.target.document.addEventListener("keypress", event => {
+    if ((event.key == "Backspace" || event.key == "Delete") && event.repeat) {
+      // Bail on delete event if there is a repeat event to prevent deleteing
+      // multiple messages by mistake from a longer key press.
+      event.preventDefault();
+      return;
+    }
+  });
 });

